package com.medflow.auth.service;
import com.medflow.auth.domain.*; import com.medflow.auth.dto.*; import com.medflow.auth.exception.ApiException; import com.medflow.auth.repository.UserAccountRepository; import com.medflow.auth.security.JwtService; import java.util.Locale; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService {
 private final UserAccountRepository users; private final PasswordEncoder passwords; private final JwtService jwt; public AuthService(UserAccountRepository u,PasswordEncoder p,JwtService j){users=u;passwords=p;jwt=j;}
 @Transactional public UserResponse register(RegisterRequest r){String email=normalize(r.email());if(users.existsByEmail(email))throw new ApiException(HttpStatus.CONFLICT,"Email is already registered");UserAccount u=new UserAccount();u.setFullName(r.fullName().trim().replaceAll("\\s+"," "));u.setEmail(email);u.setPasswordHash(passwords.encode(r.password()));u.setRole(Role.PATIENT);u.setEnabled(true);try{return UserResponse.from(users.save(u));}catch(DataIntegrityViolationException e){throw new ApiException(HttpStatus.CONFLICT,"Email is already registered");}}
 @Transactional public UserResponse createStaff(StaffCreateRequest r){if(r.role()==Role.PATIENT||r.role()==Role.ADMIN)throw new ApiException(HttpStatus.BAD_REQUEST,"Staff role must not be PATIENT or ADMIN");String email=normalize(r.email());if(users.existsByEmail(email))throw new ApiException(HttpStatus.CONFLICT,"Email is already registered");UserAccount u=new UserAccount();u.setFullName(r.fullName().trim().replaceAll("\\s+"," "));u.setEmail(email);u.setPasswordHash(passwords.encode(r.password()));u.setRole(r.role());u.setEnabled(true);try{return UserResponse.from(users.save(u));}catch(DataIntegrityViolationException e){throw new ApiException(HttpStatus.CONFLICT,"Email is already registered");}}
 @Transactional(readOnly=true) public AuthResponse login(LoginRequest r){UserAccount u=users.findByEmail(normalize(r.email())).filter(UserAccount::isEnabled).orElseThrow(this::invalid);if(!passwords.matches(r.password(),u.getPasswordHash()))throw invalid();return new AuthResponse(jwt.generate(u),"Bearer",jwt.expiresInSeconds(),UserResponse.from(u));}
 @Transactional(readOnly=true) public UserResponse me(String email){return users.findByEmail(email).map(UserResponse::from).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Authentication is required"));}
 private ApiException invalid(){return new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");} private String normalize(String v){return v.trim().toLowerCase(Locale.ROOT);}
}
